-- Migration: Year 2 - Renal/Urinary Pathology MCQ Bank (PART 1: 1-75)
-- Topics: Congenital Anomalies, Cystic Diseases, Nephritic Syndromes
-- Date: 2026-04-24

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- Ensure Topic "Renal/Urinary Pathology" exists
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Renal/Urinary Pathology', 'renal-urinary-pathology', 3, 2, 50)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- CONGENITAL & CYSTIC DISEASES (1-15)
    (v_topic_id, '1. A fetus is found to have bilateral renal agenesis. What sequence of physical findings is expected at birth?', '["Potter Sequence", "Pierre Robin Sequence", "VATER association", "Prune Belly Syndrome"]', 0, 'Bilateral renal agenesis causes oligohydramnios, leading to lung hypoplasia, flat face, and clubfeet (Potter sequence). Lung hypoplasia is usually the cause of death.'),
    (v_topic_id, '2. Horseshoe kidney is most commonly associated with which genetic syndrome?', '["Down Syndrome", "Turner Syndrome", "Edwards Syndrome", "Patau Syndrome"]', 1, 'Horseshoe kidney (fusion of the lower poles) gets caught on the Inferior Mesenteric Artery during ascent. It is strongly associated with Turner Syndrome (45,XO).'),
    (v_topic_id, '3. A neonate presents with Potter sequence and massive flank masses. Ultrasound shows enlarged kidneys with radially arranged cysts. Diagnosis?', '["Autosomal Dominant Polycystic Kidney Disease (ADPKD)", "Autosomal Recessive Polycystic Kidney Disease (ARPKD)", "Multicystic Dysplastic Kidney", "Medullary Sponge Kidney"]', 1, 'ARPKD presents in infancy with massive cystic kidneys, oligohydramnios, and is associated with congenital hepatic fibrosis (leading to portal hypertension).'),
    (v_topic_id, '4. What is the most common extrarenal manifestation of Autosomal Dominant Polycystic Kidney Disease (ADPKD)?', '["Hepatic cysts", "Berry aneurysms", "Mitral valve prolapse", "Pancreatic cysts"]', 0, 'While berry aneurysms are the most lethal complication (subarachnoid hemorrhage), hepatic cysts are the most common extrarenal manifestation of ADPKD.'),
    (v_topic_id, '5. ADPKD is caused by mutations in PKD1 or PKD2. These genes code for?', '["Aquaporins", "Polycystin", "Collagen Type IV", "Fibrocystin"]', 1, 'PKD1 (chromosome 16, 85% of cases) and PKD2 (chromosome 4) code for Polycystin-1 and Polycystin-2, which regulate tubular cell growth and cilia function.'),
    (v_topic_id, '6. A patient with ADPKD presents with a sudden, severe headache described as the "worst of my life." What has likely occurred?', '["Rupture of a berry aneurysm", "Hypertensive crisis", "Hemorrhage into a renal cyst", "Meningitis"]', 0, 'Subarachnoid hemorrhage from a ruptured berry aneurysm is a classic cause of sudden death in ADPKD.'),
    (v_topic_id, '7. Multicystic dysplastic kidney (MCDK) differs from PKD because it is?', '["Bilateral and inherited", "Unilateral and non-inherited", "Associated with berry aneurysms", "Caused by a PKD1 mutation"]', 1, 'MCDK is a non-inherited, usually unilateral congenital malformation where the kidney is replaced by cysts and abnormal tissue (cartilage). The contralateral kidney hypertrophies.'),
    (v_topic_id, '8. Medullary Cystic Kidney Disease is characterized by cysts in the medullary collecting ducts. How do the kidneys appear on ultrasound?', '["Massively enlarged", "Normal size", "Shrunken (contracted)", "Horseshoe-shaped"]', 2, 'Unlike ADPKD, Medullary Cystic Disease causes tubulointerstitial fibrosis and SHRUNKEN kidneys, leading to chronic renal failure.'),
    (v_topic_id, '9. Medullary Sponge Kidney involves cystic dilation of the collecting ducts in the medulla. It is considered benign but increases the risk for?', '["Renal Cell Carcinoma", "Kidney stones (Nephrolithiasis)", "Berry aneurysms", "Portal hypertension"]', 1, 'Medullary sponge kidney is congenital and benign but leads to urinary stasis, promoting calcium kidney stones and recurrent UTIs.'),
    (v_topic_id, '10. What is the embryological defect in a horseshoe kidney?', '["Failure of the ureteric bud to branch", "Failure of the kidneys to ascend past the inferior mesenteric artery", "Failure of the mesonephros to degenerate", "Failure of the cloaca to partition"]', 1, 'The fused lower poles of the horseshoe kidney get trapped by the IMA during their ascent from the pelvis.'),
    (v_topic_id, '11. Which of the following is an expected complication of ARPKD in a child who survives the neonatal period?', '["Berry aneurysms", "Congenital hepatic fibrosis leading to portal hypertension", "Renal Cell Carcinoma", "Deafness"]', 1, 'Hepatic fibrosis is a universal feature of ARPKD and leads to signs of portal hypertension (varices, splenomegaly) later in life.'),
    (v_topic_id, '12. A unilateral, non-inherited condition showing cysts mixed with islands of cartilage on renal biopsy in an infant is?', '["ARPKD", "ADPKD", "Multicystic dysplastic kidney", "Simple renal cyst"]', 2, 'The presence of abnormal tissue like cartilage points to dysplasia (Multicystic Dysplastic Kidney), not a genetic polycystic disease.'),
    (v_topic_id, '13. Simple renal cysts are common in adults. They appear on ultrasound as?', '["Echogenic masses with irregular borders", "Anechoic, thin-walled, fluid-filled sacs", "Solid masses with calcifications", "Multiple bilateral cysts causing enlargement"]', 1, 'Simple cysts are very common, asymptomatic, non-neoplastic, and appear anechoic (black) on US with thin, smooth walls.'),
    (v_topic_id, '14. A complex renal cyst on imaging (septations, thick walls, enhancement) raises suspicion for?', '["Renal Cell Carcinoma", "ARPKD", "Medullary Sponge Kidney", "Hydronephrosis"]', 0, 'Complex cysts must be investigated further as they can be cystic variants of Renal Cell Carcinoma.'),
    (v_topic_id, '15. Prune Belly Syndrome is characterized by a triad of?', '["Abdominal muscle deficiency, cryptorchidism, and urinary tract anomalies", "Bilateral renal agenesis, pulmonary hypoplasia, flat face", "Cystic kidneys, hepatic fibrosis, and portal hypertension", "Horseshoe kidney, webbed neck, coarctation"]', 0, 'The lack of abdominal musculature gives a "prune" appearance. It is associated with severe urinary tract dilation (e.g., posterior urethral valves).'),

    -- NEPHRITIC SYNDROME BASICS & PSGN (16-30)
    (v_topic_id, '16. The hallmark of Nephritic Syndrome is?', '["Massive proteinuria (>3.5g/day)", "Glomerular inflammation resulting in hematuria and RBC casts", "Lipiduria and oval fat bodies", "Hypoalbuminemia and severe edema"]', 1, 'Nephritic syndrome is characterized by inflammation breaking the glomerular basement membrane, allowing RBCs to leak out (hematuria, RBC casts), along with mild proteinuria, hypertension, and oliguria.'),
    (v_topic_id, '17. What type of casts are pathognomonic for glomerular bleeding (Nephritic Syndrome)?', '["Waxy casts", "Muddy brown granular casts", "Red Blood Cell (RBC) casts", "White Blood Cell (WBC) casts"]', 2, 'RBC casts form when red blood cells are compressed as they travel through the renal tubules, indicating the bleeding source is the glomerulus.'),
    (v_topic_id, '18. A 7-year-old boy presents with "cola-colored" urine, periorbital edema, and hypertension 2 weeks after a sore throat. Diagnosis?', '["IgA Nephropathy", "Post-Streptococcal Glomerulonephritis (PSGN)", "Minimal Change Disease", "Goodpasture Syndrome"]', 1, 'PSGN typically occurs 2-3 weeks after Group A Strep pharyngitis or 3-6 weeks after skin infection (impetigo).'),
    (v_topic_id, '19. What is the pathogenesis of Post-Streptococcal Glomerulonephritis?', '["Anti-GBM antibodies (Type II hypersensitivity)", "Immune complex deposition (Type III hypersensitivity)", "T-cell mediated podocyte damage", "IgA deposition"]', 1, 'PSGN is a Type III hypersensitivity reaction where circulating strep antigen-antibody complexes deposit in the glomerulus.'),
    (v_topic_id, '20. What is the classic finding on electron microscopy in PSGN?', '["Subendothelial deposits", "Intramembranous deposits", "Subepithelial ''humps''", "Effacement of podocyte foot processes"]', 2, 'Subepithelial immune complex "humps" are the hallmark of PSGN on EM.'),
    (v_topic_id, '21. What pattern is seen on Immunofluorescence (IF) in PSGN?', '["Linear IgG and C3", "Granular ''starry sky'' or ''lumpy-bumpy'' appearance", "Negative (pauci-immune)", "Mesangial IgA deposits"]', 1, 'The random deposition of immune complexes gives a "lumpy-bumpy" or granular appearance with IgG, IgM, and C3.'),
    (v_topic_id, '22. What happens to serum complement levels (specifically C3) during acute PSGN?', '["Elevated", "Normal", "Decreased", "Undetectable permanently"]', 2, 'Complement consumption by the massive immune complex deposition leads to transiently low serum C3 levels, which usually normalize within 6-8 weeks.'),
    (v_topic_id, '23. Can antibiotic treatment of Strep pharyngitis prevent PSGN?', '["Yes, always", "No, it prevents rheumatic fever but NOT PSGN", "Yes, but only if given within 24 hours", "No, it prevents neither"]', 1, 'Treating strep throat prevents Acute Rheumatic Fever, but it does NOT prevent the subsequent development of PSGN.'),
    (v_topic_id, '24. A patient with PSGN is expected to have which finding on light microscopy?', '["Normal glomeruli", "Hypercellular, enlarged glomeruli", "Crescent formation", "Nodular sclerosis"]', 1, 'The glomeruli are hypercellular (proliferation of endothelial and mesangial cells) and infiltrated by neutrophils and monocytes.'),
    (v_topic_id, '25. The majority of children with PSGN?', '["Progress to Chronic Kidney Disease", "Require dialysis for life", "Recover completely with supportive care", "Develop rapidly progressive glomerulonephritis"]', 2, 'Over 95% of children recover completely. Adults have a slightly higher risk of progressing to RPGN or CKD.'),
    (v_topic_id, '26. Which antibody is most specific for diagnosing a recent Strep infection leading to PSGN?', '["Anti-nuclear antibody (ANA)", "Anti-DNase B", "Anti-GBM", "c-ANCA"]', 1, 'Anti-DNase B and ASO (Anti-Streptolysin O) titers indicate recent Group A Strep infection.'),
    (v_topic_id, '27. PSGN can occur after skin infections (impetigo). Does Acute Rheumatic Fever occur after impetigo?', '["Yes", "No", "Only in adults", "Only in immunocompromised"]', 1, 'ARF only follows Strep pharyngitis. PSGN can follow either pharyngitis or impetigo.'),
    (v_topic_id, '28. A nephritic patient has elevated BUN and Creatinine, indicating?', '["Prerenal azotemia", "Intrinsic acute kidney injury", "Postrenal obstruction", "Normal renal function"]', 1, 'Glomerulonephritis is a cause of intrinsic acute kidney injury (AKI), leading to azotemia.'),
    (v_topic_id, '29. In nephritic syndrome, hypertension is primarily driven by?', '["Increased renin release due to renal ischemia", "Salt and water retention due to decreased GFR", "Sympathetic nervous system overactivity", "Endothelial damage"]', 1, 'The damaged glomerulus drops the GFR, leading to severe salt and fluid retention, which causes volume-dependent hypertension and edema.'),
    (v_topic_id, '30. Dysmorphic RBCs in the urine are a sign of?', '["Bladder cancer", "Kidney stones", "Glomerular bleeding", "Ureteral trauma"]', 2, 'As RBCs squeeze through the damaged glomerular basement membrane and navigate the tubules, they become dysmorphic (e.g., acanthocytes).'),

    -- RAPIDLY PROGRESSIVE GLOMERULONEPHRITIS (RPGN) (31-45)
    (v_topic_id, '31. What is the defining histological feature of Rapidly Progressive Glomerulonephritis (RPGN)?', '["Subepithelial humps", "Crescents in Bowman space", "Wire-loop lesions", "Tram-track appearance"]', 1, 'Crescents in Bowman space are the hallmark of RPGN. They consist of fibrin, macrophages, and proliferating parietal epithelial cells.'),
    (v_topic_id, '32. RPGN is a clinical syndrome characterized by?', '["Slow loss of renal function over years", "Rapid loss of renal function (days to weeks) with nephritic urine", "Massive proteinuria without hematuria", "Isolated hematuria without renal failure"]', 1, 'RPGN rapidly progresses to renal failure (often requiring dialysis) within weeks to months if untreated.'),
    (v_topic_id, '33. RPGN is divided into three types based on Immunofluorescence. Type 1 is characterized by?', '["Linear IF (Anti-GBM)", "Granular IF (Immune complex)", "Negative IF (Pauci-immune)", "IgA deposition"]', 0, 'Type 1 RPGN is Anti-GBM disease (e.g., Goodpasture syndrome). Antibodies directly attack the Type IV collagen in the GBM, leaving a smooth linear line of IgG.'),
    (v_topic_id, '34. A 25-year-old male presents with hemoptysis and hematuria. IF shows linear IgG deposition. Diagnosis?', '["Wegener Granulomatosis", "Microscopic Polyangiitis", "Goodpasture Syndrome", "Lupus Nephritis"]', 2, 'Goodpasture syndrome involves anti-GBM antibodies that attack both the alveolar basement membrane (hemoptysis) and the glomerular basement membrane (hematuria).'),
    (v_topic_id, '35. The target antigen in Goodpasture Syndrome is?', '["MPO", "PR3", "Alpha-3 chain of Type IV collagen", "PLA2R"]', 2, 'The antibodies target the alpha-3 chain of Type IV collagen.'),
    (v_topic_id, '36. Type 2 RPGN is characterized by Granular IF. What is a common cause of this type?', '["Goodpasture Syndrome", "Diffuse Proliferative Glomerulonephritis (Lupus) progressing to RPGN", "Wegener Granulomatosis", "Churg-Strauss Syndrome"]', 1, 'Any severe immune-complex glomerulonephritis (like severe PSGN or DPGN from Lupus) can be so destructive that it leads to crescent formation and Type 2 RPGN.'),
    (v_topic_id, '37. Type 3 RPGN is characterized by Negative IF (Pauci-immune). It is strongly associated with?', '["Anti-GBM antibodies", "ANCA antibodies", "Hepatitis C", "Streptococcal infections"]', 1, 'Pauci-immune RPGN lacks immune complex deposition and is usually driven by ANCA-associated vasculitides (Wegener, Microscopic Polyangiitis, Churg-Strauss).'),
    (v_topic_id, '38. A patient with Pauci-immune RPGN has chronic sinusitis, hemoptysis, and tests positive for c-ANCA (PR3-ANCA). Diagnosis?', '["Microscopic Polyangiitis", "Eosinophilic Granulomatosis with Polyangiitis (Churg-Strauss)", "Granulomatosis with Polyangiitis (Wegener)", "Goodpasture Syndrome"]', 2, 'Wegener (GPA) typically involves the upper respiratory tract (sinusitis), lower respiratory tract (hemoptysis), and kidneys (RPGN). It is strongly c-ANCA positive.'),
    (v_topic_id, '39. A patient with Pauci-immune RPGN has asthma, eosinophilia, and tests positive for p-ANCA (MPO-ANCA). Diagnosis?', '["Wegener Granulomatosis", "Churg-Strauss Syndrome", "Microscopic Polyangiitis", "IgA Nephropathy"]', 1, 'Churg-Strauss (EGPA) features asthma, peripheral eosinophilia, granulomas, and p-ANCA.'),
    (v_topic_id, '40. Microscopic Polyangiitis (MPA) differs from Wegener because MPA?', '["Is c-ANCA positive", "Involves granulomas", "Lacks granulomas and lacks nasopharyngeal involvement", "Has linear IF"]', 2, 'MPA is p-ANCA positive, involves the lungs and kidneys, but does NOT form granulomas and typically spares the upper respiratory tract/nasopharynx.'),
    (v_topic_id, '41. The crescents in RPGN are primarily composed of?', '["Neutrophils and immune complexes", "Fibrin, macrophages, and parietal epithelial cells", "Mesangial cells", "Red blood cells"]', 1, 'Fibrin leaks into Bowman space, stimulating the proliferation of parietal epithelial cells and attracting macrophages, which form the crescent.'),
    (v_topic_id, '42. Plasmapheresis is an emergent treatment option for which type of RPGN?', '["Post-streptococcal GN", "Goodpasture Syndrome (Anti-GBM)", "IgA Nephropathy", "Alport Syndrome"]', 1, 'Plasmapheresis rapidly removes the pathogenic Anti-GBM antibodies from the blood to save the lungs and kidneys in Goodpasture syndrome.'),
    (v_topic_id, '43. What is the typical appearance of the glomerulus on light microscopy in a patient with Goodpasture syndrome without RPGN features yet?', '["Normal", "Segmental necrosis", "Thickened capillary loops", "Mesangial proliferation"]', 1, 'Focal segmental necrosis can be seen early on, but it rapidly progresses to severe crescentic GN.'),
    (v_topic_id, '44. Can Systemic Lupus Erythematosus (SLE) cause RPGN?', '["No, SLE only causes nephrotic syndrome", "Yes, severe Class IV Diffuse Proliferative Lupus Nephritis can progress to Type 2 RPGN", "Yes, but it causes Pauci-immune RPGN", "No, SLE spares the kidneys"]', 1, 'Lupus Nephritis (especially Diffuse Proliferative) is an immune-complex disease that can be aggressive enough to form crescents.'),
    (v_topic_id, '45. The prognosis for RPGN if left untreated is?', '["Complete recovery", "End-Stage Renal Disease (ESRD) within weeks to months", "Mild chronic proteinuria", "Recurrent kidney stones"]', 1, 'Without aggressive immunosuppression (and sometimes plasmapheresis), RPGN rapidly destroys the kidneys.'),

    -- IGA NEPHROPATHY & ALPORT SYNDROME (46-60)
    (v_topic_id, '46. What is the most common cause of glomerulonephritis worldwide?', '["PSGN", "IgA Nephropathy (Berger Disease)", "Membranous Nephropathy", "Focal Segmental Glomerulosclerosis"]', 1, 'IgA Nephropathy is the most common primary GN worldwide, presenting with episodic gross hematuria.'),
    (v_topic_id, '47. A 20-year-old male presents with gross hematuria that started *concurrently* (within 1-2 days) with a viral upper respiratory infection. Diagnosis?', '["PSGN", "IgA Nephropathy", "Minimal Change Disease", "Goodpasture Syndrome"]', 1, 'Unlike PSGN which occurs 2-3 weeks AFTER an infection, IgA nephropathy flares up DURING or immediately after a mucosal infection (GI or respiratory) due to increased IgA production.'),
    (v_topic_id, '48. Where are the immune complexes deposited in IgA Nephropathy?', '["Subepithelial space", "Subendothelial space", "Mesangium", "Glomerular basement membrane"]', 2, 'IgA immune complexes deposit in the mesangium, causing mesangial cell proliferation.'),
    (v_topic_id, '49. What does Immunofluorescence show in IgA Nephropathy?', '["Linear IgG", "Granular IgA in the mesangium", "Granular IgG and C3 subepithelially", "Negative"]', 1, 'IF will show prominent granular deposits of IgA in the mesangial regions.'),
    (v_topic_id, '50. IgA Nephropathy is the renal manifestation of which systemic vasculitis?', '["Kawasaki Disease", "Henoch-Schönlein Purpura (IgA Vasculitis)", "Wegener Granulomatosis", "Microscopic Polyangiitis"]', 1, 'HSP features palpable purpura on the buttocks/legs, arthralgias, abdominal pain, and IgA nephropathy.'),
    (v_topic_id, '51. What happens to serum complement levels in IgA Nephropathy?', '["Severely decreased", "Normal", "Elevated", "Undetectable"]', 1, 'Unlike PSGN or Lupus Nephritis, complement levels (C3, C4) are typically NORMAL in IgA Nephropathy.'),
    (v_topic_id, '52. The long-term prognosis of IgA Nephropathy is?', '["Always benign with complete recovery", "Rapid progression to death within months", "Variable, but ~20-30% progress to End-Stage Renal Disease over decades", "Spontaneous resolution after puberty"]', 2, 'It follows a variable course, with a significant minority slowly progressing to chronic renal failure.'),
    (v_topic_id, '53. A 10-year-old boy presents with isolated microscopic hematuria, sensorineural hearing loss, and lens dislocation (anterior lenticonus). Diagnosis?', '["IgA Nephropathy", "Alport Syndrome", "Thin Basement Membrane Disease", "Goodpasture Syndrome"]', 1, 'Alport Syndrome is characterized by the triad of kidney disease (hematuria), hearing loss, and eye abnormalities ("Can''t see, can''t pee, can''t hear a bee").'),
    (v_topic_id, '54. What is the genetic defect in Alport Syndrome?', '["Mutation in the PKD1 gene", "Mutation in Type IV Collagen (COL4A3, COL4A4, COL4A5)", "Defect in Polycystin", "Anti-GBM antibodies"]', 1, 'Alport syndrome is an inherited (usually X-linked) defect in Type IV collagen, the main component of the basement membrane.'),
    (v_topic_id, '55. What is the classic finding on Electron Microscopy in Alport Syndrome?', '["Subepithelial humps", "Effacement of podocytes", "Alternating thinning and thickening with ''basket-weave'' appearance of the GBM", "Tram-track appearance"]', 2, 'The defective collagen causes the GBM to splinter and split, creating a layered "basket-weave" appearance on EM.'),
    (v_topic_id, '56. Thin Basement Membrane Lesion (Benign Familial Hematuria) is characterized by?', '["Severe renal failure by age 20", "Microscopic hematuria with normal renal function and excellent prognosis", "Hearing loss and eye defects", "Massive proteinuria"]', 1, 'It is an autosomal dominant condition with thinning of the GBM causing asymptomatic microscopic hematuria but no progression to renal failure.'),
    (v_topic_id, '57. In Alport syndrome, what happens if the patient receives a kidney transplant?', '["The transplant works perfectly forever", "The patient may develop Anti-GBM disease against the normal transplanted kidney", "The disease immediately recurs in the transplant", "The body rejects the kidney due to HLA mismatch"]', 1, 'Because the patient''s immune system has never seen normal Type IV collagen, it may recognize the new, healthy kidney''s collagen as foreign, forming Anti-GBM antibodies.'),
    (v_topic_id, '58. The most common inheritance pattern of Alport syndrome is?', '["Autosomal Dominant", "Autosomal Recessive", "X-linked Recessive", "Mitochondrial"]', 2, 'About 80% of Alport cases are X-linked, meaning males are much more severely affected (progressing to ESRD), while female carriers often only have microscopic hematuria.'),
    (v_topic_id, '59. How does the hematuria of IgA nephropathy differ clinically from PSGN?', '["IgA hematuria is continuous, PSGN is episodic", "IgA hematuria flares with infections, PSGN occurs weeks after", "PSGN causes gross hematuria, IgA only causes microscopic", "They are identical clinically"]', 1, 'IgA flares concurrently with infections ("synpharyngitic"), whereas PSGN has a distinct latent period (1-3 weeks).'),
    (v_topic_id, '60. Diffuse Proliferative Glomerulonephritis (DPGN) is the most common and severe renal lesion in?', '["Rheumatoid Arthritis", "Systemic Lupus Erythematosus (SLE)", "Sjogren Syndrome", "Scleroderma"]', 1, 'DPGN is Class IV Lupus Nephritis. It presents as a nephritic syndrome (sometimes with nephrotic-range proteinuria) and is highly active and destructive.'),

    -- MEMBRANOPROLIFERATIVE GLOMERULONEPHRITIS (MPGN) (61-75)
    (v_topic_id, '61. Membranoproliferative Glomerulonephritis (MPGN) often presents with?', '["Pure nephritic syndrome", "Pure nephrotic syndrome", "A mixed nephritic-nephrotic picture", "Isolated asymptomatic proteinuria"]', 2, 'MPGN frequently presents with features of both nephritic (hematuria, inflammation) and nephrotic (>3.5g proteinuria) syndromes.'),
    (v_topic_id, '62. What is the classic appearance of the capillary loops on light microscopy in MPGN?', '["Wire-loop lesions", "Tram-track appearance", "Crescents", "Kimmelstiel-Wilson nodules"]', 1, 'Mesangial cells grow into the capillary wall, splitting the basement membrane and creating a double contour or "tram-track" appearance (best seen on silver stain).'),
    (v_topic_id, '63. Type I MPGN is characterized by immune complex deposition in which location?', '["Subepithelial space", "Subendothelial space", "Intramembranous space", "Mesangium only"]', 1, 'Type I MPGN involves subendothelial immune complex deposits.'),
    (v_topic_id, '64. Type I MPGN is highly associated with which chronic infection?', '["HIV", "Hepatitis B and Hepatitis C", "Syphilis", "Tuberculosis"]', 1, 'Type I MPGN is classically associated with Hepatitis B and C, as well as cryoglobulinemia.'),
    (v_topic_id, '65. Type II MPGN is also known as?', '["Dense Deposit Disease", "Goodpasture Syndrome", "IgA Nephropathy", "Focal Segmental Glomerulosclerosis"]', 0, 'Type II is called Dense Deposit Disease because of dense material deposited WITHIN the basement membrane (intramembranous).'),
    (v_topic_id, '66. The pathogenesis of Type II MPGN (Dense Deposit Disease) involves an autoantibody called C3 Nephritic Factor. What does this antibody do?', '["Destroys the C3 convertase", "Stabilizes the alternate pathway C3 convertase, leading to continuous complement activation", "Directly attacks the basement membrane", "Binds to IgA in the mesangium"]', 1, 'C3 Nephritic Factor binds and stabilizes C3 convertase, preventing its breakdown. This leads to massive, unregulated cleavage of C3 and persistently low serum C3 levels.'),
    (v_topic_id, '67. What happens to serum C3 levels in Type II MPGN?', '["Elevated", "Normal", "Persistently low", "Transiently low then recovers"]', 2, 'Because C3 Nephritic Factor constantly activates complement, serum C3 is continually consumed and remains persistently low.'),
    (v_topic_id, '68. In Type I MPGN, what is the composition of the subendothelial deposits?', '["IgA", "IgG and C3", "C3 only", "Fibrin only"]', 1, 'Type I is an immune complex disease, so deposits contain both immunoglobulins (IgG/IgM) and complement (C3).'),
    (v_topic_id, '69. In Type II MPGN (Dense Deposit Disease), what is the composition of the intramembranous deposits?', '["IgG and C3", "IgA only", "C3 only (no immunoglobulins)", "IgM and C4"]', 2, 'Because Type II is driven by complement dysregulation (C3 Nephritic Factor), the deposits are almost exclusively C3, with NO significant immunoglobulins.'),
    (v_topic_id, '70. A patient with Hepatitis C develops a mixed nephritic/nephrotic syndrome. Biopsy shows tram-tracking. Diagnosis?', '["Membranous Nephropathy", "Type I MPGN", "Type II MPGN", "IgA Nephropathy"]', 1, 'Hepatitis C + tram-tracking = Type I MPGN.'),
    (v_topic_id, '71. Wire-loop lesions on light microscopy are the hallmark of?', '["IgA Nephropathy", "Diffuse Proliferative Glomerulonephritis (Lupus)", "Minimal Change Disease", "Goodpasture Syndrome"]', 1, 'Thickened capillary loops ("wire loops") due to massive subendothelial immune complex deposition are characteristic of Diffuse Proliferative Glomerulonephritis (Class IV Lupus).'),
    (v_topic_id, '72. DPGN (Lupus Nephritis Class IV) deposits are located in the?', '["Subepithelial space", "Mesangium", "Subendothelial space", "Intramembranous space"]', 2, 'The massive immune complexes in DPGN deposit subendothelially, creating the thick "wire loops".'),
    (v_topic_id, '73. Which of the following stains positive for all immunoglobulins and complement ("Full House" pattern on IF)?', '["IgA Nephropathy", "Goodpasture Syndrome", "Diffuse Proliferative Glomerulonephritis (Lupus)", "PSGN"]', 2, 'Lupus Nephritis typically stains positive for IgG, IgA, IgM, C3, and C1q, giving a "full house" immunofluorescence pattern.'),
    (v_topic_id, '74. Patients with DPGN often have a history of?', '["Recent Strep infection", "Hepatitis C", "Systemic Lupus Erythematosus (malar rash, ANA+, anti-dsDNA+)", "ANCA vasculitis"]', 2, 'DPGN is the most severe and common renal manifestation of SLE.'),
    (v_topic_id, '75. What is the most common cause of death in patients with Systemic Lupus Erythematosus?', '["Infection", "Cardiovascular disease", "Renal failure (from Lupus Nephritis)", "CNS lupus"]', 2, 'Renal failure secondary to severe Lupus Nephritis (usually DPGN) is historically a leading cause of morbidity and mortality in SLE.');

    RAISE NOTICE 'SUCCESS: Renal Pathology MCQs Part 1 (1-75) registered.';
END $$;

COMMIT;
